7	/**
8	 * Normalizes a create-owner telephone into E.164 form: a leading '+' and country code are kept
9	 * when present, otherwise country code '+61' is assumed and a single leading '0' is dropped from
10	 * the national digits. Spaces, dashes and brackets are stripped, and 8 to 15 digits are required
11	 * after the '+'. The national-number length must also match the country code ('+61' requires 9
12	 * national digits, '+1' requires 10). Mutates the validated {@link OwnerFieldsDto} in place (so
13	 * {@link BuildOwner} stores the E.164 value), or throws {@link InvalidTelephoneException} for a 400
14	 * when the value cannot form a valid E.164 number or its national length is wrong for the country.
15	 */
16	public class NormalizeOwnerTelephone {
17	
18	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
19	        String original = request.getTelephone();
20	        String e164 = TelephoneE164.toE164(original);
21	        if (e164 == null || !TelephoneE164.nationalLengthValid(e164)) {
22	            throw new InvalidTelephoneException(original);
23	        }
24	        request.setTelephone(e164);
25	    }
26	}
