3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.Locale;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
14	
15	/**
16	 * Joins a deliberately-shared household. When the create request opts in via
17	 * {@code sharesHousehold} and an existing owner has the same last name and address (the address in
18	 * its normalized form and the last name case-insensitively with whitespace collapsed), the new
19	 * owner and the existing household member(s) are given the same, stable
20	 * {@code householdId}. If a matching owner already carries a household id it is reused; otherwise a
21	 * new id is derived from the household's normalized last name and address, so the same household
22	 * always yields the same value. Does nothing when the request does not opt in or no matching owner
23	 * exists — a lone owner has no household to share.
24	 */
25	public class AssignHousehold {
26	
27	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
28	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
29	            return;
30	        }
31	        String lastName = normalizeName(owner.getLastName());
32	        String address = AddressNormalizer.normalize(owner.getAddress());
33	        List<Owner> household = new ArrayList<>();
34	        String existingId = null;
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (lastName.equals(normalizeName(existing.getLastName()))
37	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
38	                household.add(existing);
39	                if (existingId == null && existing.getHouseholdId() != null) {
40	                    existingId = existing.getHouseholdId();
41	                }
42	            }
43	        }
44	        if (household.isEmpty()) {
45	            return; // nobody to share a household with
46	        }
47	        String householdId = existingId != null ? existingId : deriveHouseholdId(lastName, address);
48	        owner.setHouseholdId(householdId);
49	        for (Owner member : household) {
50	            if (member.getHouseholdId() == null) {
51	                member.setHouseholdId(householdId);
52	                ownerRepository.save(member);
53	            }
54	        }
55	    }
56	
57	    /** A stable {@code HH-<12 upper hex>} id derived from the household's normalized identity. */
58	    private static String deriveHouseholdId(String lastName, String address) {
59	        try {
60	            byte[] digest = MessageDigest.getInstance("SHA-256")
61	                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
62	            StringBuilder sb = new StringBuilder("HH-");
63	            for (int i = 0; i < 6; i++) {
64	                sb.append(String.format("%02X", digest[i]));
65	            }
66	            return sb.toString();
67	        }
68	        catch (NoSuchAlgorithmException e) {
69	            throw new IllegalStateException("SHA-256 unavailable", e);
70	        }
71	    }
72	
73	    /** Trim, collapse internal whitespace runs to a single space, and lower-case. */
74	    private static String normalizeName(String value) {
75	        if (value == null) {
76	            return "";
77	        }
78	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
79	    }
80	}
