1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Canonical form for an owner address, applied whenever an owner is created. Trims and collapses
8	 * runs of whitespace to a single space, upper-cases, and expands common abbreviations
9	 * ({@code ST}&nbsp;&rarr;&nbsp;{@code STREET}, {@code RD}&nbsp;&rarr;&nbsp;{@code ROAD},
10	 * {@code AVE}&nbsp;&rarr;&nbsp;{@code AVENUE}) as whole words. A {@code null} or blank value
11	 * normalizes to the empty string. The result is idempotent, so an already-normalized address is
12	 * returned unchanged. This is the single source of truth every address comparison uses.
13	 */
14	public final class AddressNormalizer {
15	
16	    private static final Map<String, String> ABBREVIATIONS = Map.of(
17	            "ST", "STREET",
18	            "RD", "ROAD",
19	            "AVE", "AVENUE");
20	
21	    private AddressNormalizer() {
22	    }
23	
24	    /** Normalize an address to its canonical stored/returned form. */
25	    public static String normalize(String value) {
26	        if (value == null) {
27	            return "";
28	        }
29	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
30	        if (collapsed.isEmpty()) {
31	            return "";
32	        }
33	        String[] tokens = collapsed.split(" ");
34	        StringBuilder sb = new StringBuilder(collapsed.length());
35	        for (int i = 0; i < tokens.length; i++) {
36	            if (i > 0) {
37	                sb.append(' ');
38	            }
39	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
40	        }
41	        return sb.toString();
42	    }
43	}
